# Generated by Selenium IDE / Pytest for SGCS Project
import pytest
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC

class TestCitizenFeedback:
    def setup_method(self, method):
        # Initialize Chrome WebDriver with options
        options = webdriver.ChromeOptions()
        options.add_argument("--start-maximized")
        self.driver = webdriver.Chrome(options=options)
        self.wait = WebDriverWait(self.driver, 10)  # Explicit wait

    def teardown_method(self, method):
        self.driver.quit()

    def test_submit_citizen_feedback(self):
        # Step 1: Open Application Login Page
        self.driver.get("http://localhost:5173/login")

        # Step 2: Login as Citizen
        email_field = self.wait.until(EC.visibility_of_element_located((By.NAME, "email")))
        email_field.send_keys("citizen@example.com")

        password_field = self.wait.until(EC.visibility_of_element_located((By.NAME, "password")))
        password_field.send_keys("Citizen@123")

        login_btn = self.wait.until(EC.element_to_be_clickable((By.CSS_SELECTOR, "button[type='submit']")))
        login_btn.click()

        # Step 3: Navigate to Resolved Complaint Details
        time.sleep(2)
        self.driver.get("http://localhost:5173/complaints")
        
        # Click on the first resolved complaint
        resolved_card = self.wait.until(EC.element_to_be_clickable((By.XPATH, "//div[contains(text(), 'Resolved') or contains(., 'Resolved')]")))
        resolved_card.click()

        # Step 4: Locate Feedback Section & Select 5-Star Rating
        rating_star = self.wait.until(EC.element_to_be_clickable((By.XPATH, "//label[contains(@for, '5')] | //span[contains(@class, 'MuiRating-decimal')][5]")))
        rating_star.click()

        # Step 5: Select "Yes, Satisfied" radio button
        satisfied_radio = self.wait.until(EC.element_to_be_clickable((By.XPATH, "//input[@value='Yes']")))
        self.driver.execute_script("arguments[0].click();", satisfied_radio)

        # Step 6: Enter Feedback Details Comment
        comment_box = self.wait.until(EC.visibility_of_element_located((By.XPATH, "//textarea[@placeholder='Optional feedback details...']")))
        comment_box.clear()
        comment_box.send_keys("The road repair work was completed promptly and satisfactorily. Excellent work by the municipal ward team!")

        # Step 7: Click on Submit Feedback Button
        submit_btn = self.wait.until(EC.element_to_be_clickable((By.XPATH, "//button[contains(., 'Submit Feedback')]")))
        submit_btn.click()

        # Step 8: Assert Feedback Confirmation
        success_alert = self.wait.until(EC.visibility_of_element_located((By.XPATH, "//*[contains(text(), 'Thank you! Your resolution feedback has been recorded')]")))
        assert success_alert.is_displayed(), "Feedback submission confirmation not visible!"
        
        # Optional pause for visual verification
        time.sleep(3)

if __name__ == "__main__":
    pytest.main(["-v", __file__])
